-- Observabilidade minima: erros 5xx do servidor (HTTP e tRPC).
--
-- Por que uma tabela e nao um SaaS: o objetivo imediato e responder "o que
-- quebrou, onde e desde quando" sem depender de conta externa nem de deploy de
-- agente. O webhook opcional (ALERT_WEBHOOK_URL) avisa Slack/Discord; a tabela
-- guarda o historico para diagnostico. `fingerprint` agrupa ocorrencias iguais
-- (rota + codigo + frame de stack normalizado) e evita alerta por requisicao.
CREATE TABLE "error_events" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fingerprint" varchar(64) NOT NULL,
  "origem" varchar(16) NOT NULL,
  "rota" varchar(300) NOT NULL,
  "metodo" varchar(10),
  "status" integer NOT NULL,
  "codigo" varchar(80),
  "mensagem" text NOT NULL,
  "stack" text,
  "userId" integer,
  "commitSha" varchar(40),
  "createdAt" timestamp with time zone DEFAULT now() NOT NULL
);

--> statement-breakpoint
CREATE INDEX "error_events_createdAt_idx" ON "error_events" USING btree ("createdAt");

--> statement-breakpoint
CREATE INDEX "error_events_fingerprint_createdAt_idx" ON "error_events" USING btree ("fingerprint","createdAt");
